from pathlib import Path
import collections,json
from service_docs import ROOT,BASE,DIRECTORIES,dump
FEATURES={
 'firecrawl':'Поиск, scrape, карта и обход сайтов; пакетное чтение; parse документов; структурное извлечение; исследовательский агент; научный и технический поиск; мониторинг изменений; управляемый браузер. Интерактивные действия, публикации и мониторинг отделены от чтения.',
 'exa':'Обычный, расширенный и глубокий поиск; домены, даты, категории, текст, выдержки и снимки; Contents, Answer и похожие страницы; исследовательский Agent; списки Websets, обогащение, партии и мониторинг. Администрирование ключей и платежи не включаются в исследовательский доступ.',
 'tavily':'Search general/news/finance со всеми объявленными глубинами, датами, доменами и дополнительными полями; Extract; Map; Crawl; Research, статус, поток; Usage и Logs. Машинный ответ не подменяет чтение источника; проверяются failed_results и расход.',
 'keenable':'Веб-поиск, чтение страниц и расширенные параметры HTTP API; SELECT по нескольким источникам; формирование и снятие HTML-отчётов. Отчёт по общедоступной ссылке требует отдельного подтверждения точного содержания.',
 'nimble':'Search, SERP, Map, Extract и Media; шаблоны и их версии; синхронные, отложенные и пакетные операции; обход; агенты, задания, результаты и артефакты. Справочный MCP отделён от поиска в сети. Названия уровней и фактические поля берутся из текущей схемы.',
 'parallel':'Search с режимами и бюджетом выдержек; Extract, изображения и решения с источниками; Task Runs и группы; FindAll, обогащение и продолжение; мониторы и API памяти. Созданное задание продолжается по прежнему ID, а не запускается повторно.',
 'consensus':'Поиск научных работ с полным набором объявленных фильтров, извлечений и параметров; создание, дополнение, поиск и чтение исследовательских обсуждений. Аннотация, выдержки и весь текст различаются явно.',
 'scite':'Поиск литературы и доступного текста; контексты и граф цитирования; библиография и проверяемый реестр использованных ссылок; коллекции, заметки и файлы; дополнительные научные, патентные, грантовые, клинические и регуляторные инструменты из фактического каталога. Категория цитирования не является доказательством истинности вывода.',
 'undermind':'Поиск и глубокий поиск, чтение PDF по запросам, сведения о статьях и ссылки, организация рабочих областей, папок, файлов и поисков. Ориентация, состояние заданий и сохранённые результаты позволяют продолжать работу после перерыва. Извлечённый ответ обработчика не называется просмотром исходных страниц.',
 'alphaxiv':'Обнаружение статей и исследователей; текст, обзор ИИ и адресные PDF-выдержки; чтение кода GitHub; ленты, библиотека, папки, подписки и частные метаданные. fullText=false может вернуть машинный обзор; это явно маркируется.',
 'semanticscholar':'Авторы и работы: поиск, точное сопоставление, партии, детали, ссылки и цитирования; рекомендации; сниппеты и наборы данных. Публичный режим сохранён; функции, требующие ключа/разрешения, не выдаются за доступные. HTTP 429 прекращает запросы к этому сервису.',
 'pubmed':'Полный набор выбранных E-utilities: поиск, история, сводки, записи, связи, поля, исправление и сопоставление цитат; PMC metadata, лицензия, версии, секции, таблицы, текст и PDF. Контакт NCBI хранится в собственных настройках, не берётся из модельного аргумента.',
 'russianresearch':'Отдельные маршруты eLIBRARY, DisserCat и КиберЛенинки: план запроса, внешнее обнаружение с явным реальным поставщиком, разрешение DOI, импорт предоставленных документов, страницы, поиск по тексту, метаданные и запрос разрешения. Прямой доступ к площадкам остаётся закрытым до основания доступа.',
 'webofscience':'Планы и каталоги Starter, Expanded, Researcher, Journals/JCR и InCites, подготовка обращения и статус разрешений. Получение данных зависит от лицензии и разрешения на использование с языковой моделью; заглушка не снимается технической настройкой.',
 'pendar':'Проверка статьи, обзор области, переходы по графу, аудит библиографии, профиль исследователя и поиск журналов. Собственный OAuth BNN, только исследовательские чтения; отсутствие кредитов является отсутствием подтверждённой деловой работоспособности.',
 'scholarsidekick':'Разрешение DOI/PMID/PMCID/ISBN/ISSN/arXiv/ADS/WHO IRIS; форматирование, партии и экспорты; проверка существования, отзыва и открытого доступа. Проверка библиографической записи не является оценкой результатов статьи; платное модельное просеивание не включается молча.',
 'wolfram':'Контекст выбора инструментов, WolframAlpha и облачный WolframLanguageEvaluator: расчёты, единицы, статистика, символические выражения и графики. Облачный режим не подменяется несуществующей локальной лицензией.',
 'rstats':'Официальный R.framework/R.app; справка и сведения о пакетах, окружении и данных; CRAN; вычисления, статистика и графики через реальные инструменты btw/mcptools. Отдельная библиотека нативных пакетов, запрет дочерних процессов, чужих файлов и сети при выполнении произвольного R-кода.',
 'zotero':'Схемы и шаблоны, поиск и карточки, коллекции, теги, полные тексты и вложения, PDF-страницы, экспорты, заметки, аннотации, индексация и обратимые изменения своей изолированной библиотеки. Не перепривязывает производственную библиотеку BN.',
 'crossref':'REST-поиск и записи, партии, сопоставление библиографии, агентство DOI, связи, исправления, финансирование, лицензии, сущности, фасеты, выборки и форматы; XML, OpenURL и beta data citations. Отличаются даты публикации, регистрации и обновления.',
 'openalex':'Официальный MCP для поиска, сущностей, ссылок, цитирований, группировок, расчётов, OQL и справки; API-переходник для семантического поиска, аннотаций, метрик, контента, PDF, экспорта и сохранённых запросов. Исправление авторского профиля остаётся закрытым.',
 'asreview':'Подготовка и проверка данных, проекты, протокол и модель, обучение и ранжирование, следующий пакет, предложения и решения, журнал, прогресс, аудит, симуляции, сравнение, экспорт/импорт и график. Ранжирование не означает включение; полнота нахождения не вычисляется на неразмеченном корпусе.',
 'beads':'Первичные задачи всей работы BNN, декомпозиция, зависимости, готовность, история, результаты и возобновление через действующие собственные work_plan/work_team и bd-bnn. Старый сервер BN не переподключается.',
 'dolt':'Собственная версия данных kw_core, закреплённые хеши/ветки и связи с Beads через существующие BNN memory_data и операторские интерфейсы. Старый SQL-порт BN не используется; прежние каталоги не являются допуском к другой базе.',
}
GROUPS={'parallel':['parallel-search','parallel-task'],'keenable':['keenable','keenable-select'],'nimble':['nimble','nimble-docs'],'openalex':['openalex','openalex-api'],'beads':['beads'],'dolt':['dolt','beads-dolt']}
GROUPS.update(tinyfish=['tinyfish','tinyfish-api'],elicit=['elicit','elicit-api'])
FEATURES.update(datacite='Public REST: поиск и чтение DOI данных, программ и публикаций, связи, события, репозитории, организации, префиксы и статистика. Создание DOI не разрешается.',tinyfish='Поиск, извлечение, исследовательские задания, браузерные сценарии и мониторинг по шести официальным API. Браузерные действия требуют точного допуска владельца; CDP, хранилище паролей, платежи и неадаптированные потоки закрыты. MCP-каталог получается только после штатного доступа.',wiley='Новый официальный MCP v2: издательский поиск Wiley и сведения о квоте. Без отдельного входа и живого каталога методы не выдумываются.',scispace='Официальный MCP для научного поиска и таблиц. HTTP 403 фиксируется как отсутствие живого каталога, не заменяется неофициальным обходом.',elicit='Официальный API v2 и отдельный MCP: поиск, отчёты, обзоры, сеансы исследовательского агента, источники, библиотека, проекты и расписания. API требует соответствующего плана; Basic не объявляется достаточным.',synapse='Sage Bionetworks: ограниченный исследовательский REST-каталог метаданных, версий, происхождения, поиска и запросов к таблицам. Права конкретных данных проверяет поставщик; управление аккаунтами и разрешениями не подключено.')
def generate():
 previous_file=BASE/'requirements-mechanisms-checks.json'
 previous={(r['service'],r['method']):r for r in json.loads(previous_file.read_text())} if previous_file.exists() else {}
 cfg=json.loads((BASE/'candidate-settings.private.json').read_text());cat=json.loads((Path(cfg['package_root'])/'services/catalogue.json').read_text())['services']
 sources=json.loads((BASE/'documentation-ledger.json').read_text())['sources'];index=[];matrix=[]
 for group,feature in FEATURES.items():
  servers=GROUPS.get(group,[group]);entries={n:cat.get(n,{'methods':{},'status':'not_in_candidate'}) for n in servers};docs=[x for x in sources if x['service']==group]
  counts=collections.Counter(m['effect'] for e in entries.values() for m in e['methods'].values())
  rows=[]
  for server,e in entries.items():
   for pos,(method,m) in enumerate(e['methods'].items(),1):
    rid=group.upper()+'-'+server.upper()+'-'+str(pos).zfill(3)
    row={'requirement_id':rid,'service':server,'method':method,'effect':m['effect'],'source_id':m.get('source_sha256',e.get('catalogue_source_sha256')),'input_schema_sha256':m['schema_sha256'],'mechanism':'native context RPC + typed service_'+m['effect'] if m['effect']!='blocked' else 'trusted pre-action refusal','implemented':m['effect']!='blocked','connected':not e.get('status','').startswith('awaiting_access') and m['effect']!='blocked','actual_result':'trusted_refusal_or_documented_replacement' if m['effect']=='blocked' else 'not_individually_exercised','check':'exact schema, effect, input attenuation, provider outcome, immutable full result and consumer evidence'}
    prior=previous.get((server,method),{})
    if prior.get('input_schema_sha256')==m['schema_sha256'] and prior.get('effect')==m['effect']:
     for key in ['actual_result','individually_vendor_exercised','scientific_acceptance']:row[key]=prior.get(key,row.get(key))
     if prior.get('actual_result')=='success':row['last_qualified_release']=prior.get('last_qualified_release','2.0.0-dev.40')
    matrix.append(row)
    rows.append('| `'+rid+'` | `'+server+'` | `'+method+'` | '+m['effect']+' | '+('API' if m.get('api_request') else 'MCP')+' |')
  text='# '+DIRECTORIES[group]+': план полной интеграции в Hermes BNN\n\n## Назначение и полный функциональный охват\n\n'+feature+'\n\n## Интерфейс и механизм\n\n'
  text+='Точные текущие схемы закрепляются в версионном каталоге. Основной агент обращается через service_catalog и service_read/job/write; полные ответы сохраняются с контрольной суммой и читаются страницами до next_offset=null. Чтение не зависит от включённости GSD, UDR или Foundation. UDR/work_team получает service_calls, G/S/D получает assigned_service_calls по ролям; метод и исходные аргументы сужаются доверенным слоем. Дочерние агенты не запускают исследования и не меняют данные сервиса.\n\n'
  text+='## Последовательность подключения\n\n1. Проверить индекс документации и фактический каталог, сопоставить прежние и новые методы.\n2. Использовать собственное хранилище BNN: API-ключи не попадают в модель; OAuth обновляется только в независимом профиле.\n3. Сохранить первичные ограничения доступа, отделить чтение, задания, локальные изменения, внешние изменения и запрещённое администрирование.\n4. Подключить основной агент и точные назначения субагентов без обхода пяти обязательных контроллеров.\n5. Выполнить безопасный реальный запрос, проверить содержание ответа и ограничения, повторное чтение, отсутствие повторной оплаты, происхождение и отрицательные границы.\n6. Проверить подходящие расширенные операции; для внешних изменений сначала предъявить точный запрос владельцу.\n7. Зафиксировать отдельно установленное, подключённое и проверенное; обновить переносимый комплект.\n\n'
  text+='## Доступ и существенные границы\n\n'
  if group=='pendar':text+='При подтверждении OAuth интерфейс показал 0 кредитов. Соединение и схемы подтверждены; успешный исследовательский вызов не установлен до появления доступного остатка. Покупки не выполняются.\n\n'
  if group in {'webofscience','russianresearch','semanticscholar'}:text+='Прежняя заглушка/ограничение доступа сохраняется. Наличие схем не означает получения закрытых данных. Отказ не обходится чужим ключом или скрытой подменой поставщика.\n\n'
  if group in {'beads','dolt'}:text+='Текущий собственный маршрут BNN сохраняется. Старые MCP-порты и базы BN не перепривязываются. Полная совместимость всех старых методов другого хранилища не заявляется.\n\n'
  text+='Проверка структуры и схем не доказывает научную корректность или испытание каждой допустимой комбинации параметров. HTTP-ошибка, неполный ответ, пустой результат, истёкший вход и неопределённый исход различаются.\n\n'
  text+='## Карта всех объявленных операций\n\n'+str(sum(counts.values()))+' методов; '+', '.join(k+': '+str(counts[k]) for k in ['read','job','write','blocked'])+'.\n\n| ID | Сервер | Метод | Режим | Интерфейс |\n|---|---|---|---|---|\n'+'\n'.join(rows)+'\n\n'
  text+='## Источники и полнота обработки\n\nПолучено '+str(len(docs))+' адресов; HTTP 200: '+str(sum(x.get('http_status')==200 for x in docs))+'. Полные байты и контрольные суммы сохранены локально в documentation-ledger.json. Весь доступный текст обработан структурно, спецификации API разобраны целиком. Скачивание/структурный разбор не объявляется смысловой приёмкой каждой страницы.\n\n'
  text+='| ID источника | Адрес | HTTP | Байты |\n|---|---|---:|---:|\n'+''.join('| `'+x.get('sha256','unavailable')+'` | '+x['url']+' | '+str(x.get('http_status','н/д'))+' | '+str(x.get('bytes',0))+' |\n' for x in docs)
  dest=BASE/'plans'/(DIRECTORIES[group]+'.md');dest.parent.mkdir(exist_ok=True);dest.write_text(text)
  index.append({'service':group,'plan':str(dest.relative_to(BASE)),'servers':servers,'declared_methods':sum(counts.values()),'effects':dict(counts),'documentation_addresses':len(docs),'semantic_documentation_acceptance':'not_established_by_download'})
 dump(BASE/'service-plans.json',index);dump(BASE/'requirements-mechanisms-checks.json',matrix)
 (BASE/'README.md').write_text('# Исследовательские сервисы Hermes BNN\n\nЗадача bnn-x4y.28. Кандидат '+Path(cfg['package_root']).name+'.\n\n'+''.join('- ['+DIRECTORIES[x['service']]+']('+x['plan']+'): '+str(x['declared_methods'])+' объявленных методов.\n' for x in index)+'\nМашиночитаемая матрица: requirements-mechanisms-checks.json. Наличие в каталоге, подключение и успешная работа отмечаются отдельно.\n')
 return {'plans':len(index),'declared_methods':len(matrix),'documentation_addresses':len(sources),'claimed_all_pages_semantically_accepted':False}
